export function getItems(t){const o=document.querySelector(t?.rootSelector||"[data-docs-content]");if(!o)return[];const l=t?.headingSelector||"h2[id], h3[id]",n=t?.ignoreSelector||"[data-docs-ignore-toc]",r=[];for(const e of o.querySelectorAll(l)){if(n&&e.closest(n))continue;const c=e.id,i=e.textContent?.trim(),s=Number(e.tagName.substring(1));c&&i&&Number.isFinite(s)&&r.push({id:c,title:i,level:s})}return r}
